-- Dua Dev internal tool — seed data
-- Run this AFTER schema.sql, in the Supabase SQL editor.
--
-- Part 1 creates your login (Sara Malik, CTO, workspace admin) directly — email +
-- password, ready to sign in with immediately, no dashboard steps needed.
-- Part 2 loads the real outreach data (the firm contact list PDF) with its send
-- dates. Both parts are safe to re-run. Skip Part 2 to start with no firms.

-- ============================================================================
-- PART 1 — your leadership login
--   Email:    saramalik@dua-dev.com
--   Password: 0IIL+mj0aksA5SYE
--   Role:     CTO
-- Change the password any time from the app's own "forgot password" flow,
-- or Authentication -> Users in the Supabase dashboard.
-- ============================================================================

do $$
declare
  v_user_id uuid := gen_random_uuid();
  v_email text := 'saramalik@dua-dev.com';
  v_password text := '0IIL+mj0aksA5SYE';
begin
  if exists (select 1 from auth.users where email = v_email) then
    raise notice 'A user with email % already exists — skipping creation. If you need a fresh password, use Authentication -> Users -> Reset Password in the dashboard instead.', v_email;
  else
    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password,
      email_confirmed_at, created_at, updated_at,
      raw_app_meta_data, raw_user_meta_data,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) values (
      '00000000-0000-0000-0000-000000000000',
      v_user_id, 'authenticated', 'authenticated',
      v_email, crypt(v_password, gen_salt('bf')),
      now(), now(), now(),
      '{"provider":"email","providers":["email"]}', '{}',
      '', '', '', ''
    );

    insert into auth.identities (
      id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at
    ) values (
      gen_random_uuid(), v_user_id, v_user_id::text,
      jsonb_build_object('sub', v_user_id::text, 'email', v_email),
      'email', now(), now(), now()
    );

    insert into app_users (id, full_name, role, account_role)
    values (v_user_id, 'Sara Malik', 'CTO', 'admin');

    raise notice 'Created % (CTO, workspace admin) — sign in at /login with the password from this script.', v_email;
  end if;
end $$;

